class OrderTrackingScreen extends StatelessWidget {
  const OrderTrackingScreen({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    final stages = ['Order Placed', 'Processing', 'Shipped', 'Out for Delivery', 'Delivered'];
    final currentStage = 2;

    return Scaffold(
      appBar: AppBar(title: const Text('Track Order #1042')),
      body: ListView.builder(
        padding: const EdgeInsets.all(24.0),
        itemCount: stages.length,
        itemBuilder: (context, index) {
          bool isCompleted = index <= currentStage;
          bool isLast = index == stages.length - 1;
          return Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Column(
                children: [
                  Container(width: 20, height: 20, decoration: BoxDecoration(shape: BoxShape.circle, color: isCompleted ? Colors.green : Colors.grey[300]), child: isCompleted ? const Icon(Icons.check, size: 14, color: Colors.white) : null),
                  if (!isLast) Container(width: 2, height: 50, color: isCompleted ? Colors.green : Colors.grey[300]),
                ],
              ),
              const SizedBox(width: 20),
              Expanded(
                child: Padding(
                  padding: const EdgeInsets.only(bottom: 30.0),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(stages[index], style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold, color: isCompleted ? Colors.black : Colors.grey)),
                      if (isCompleted) const Text('Oct 15, 10:30 AM', style: TextStyle(color: Colors.grey, fontSize: 12)),
                    ],
                  ),
                ),
              )
            ],
          );
        },
      ),
    );
  }
}

