class SeatSelectionScreen extends StatefulWidget {
  const SeatSelectionScreen({Key? key}) : super(key: key);
  @override
  State<SeatSelectionScreen> createState() => _SeatSelectionScreenState();
}

class _SeatSelectionScreenState extends State<SeatSelectionScreen> {
  int _selectedSeatIndex = -1;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Select Your Seat')),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                _buildLegend(Colors.grey, 'Available'),
                _buildLegend(Colors.blue, 'Selected'),
                _buildLegend(Colors.red[200]!, 'Booked'),
              ],
            ),
          ),
          Expanded(
            child: GridView.builder(
              padding: const EdgeInsets.symmetric(horizontal: 40, vertical: 20),
              gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount: 5, childAspectRatio: 1, crossAxisSpacing: 10, mainAxisSpacing: 20),
              itemCount: 40,
              itemBuilder: (context, index) {
                if (index % 5 == 2) return const Center(child: Text('Aisle', style: TextStyle(color: Colors.grey, fontSize: 10))); // Aisle space
                bool isBooked = index == 4 || index == 5 || index == 18;
                bool isSelected = _selectedSeatIndex == index;
                Color iconColor = isBooked ? Colors.red[200]! : (isSelected ? Colors.blue : Colors.grey);
                return GestureDetector(
                  onTap: () { if (!isBooked) setState(() { _selectedSeatIndex = index; }); },
                  child: Icon(Icons.event_seat, color: iconColor, size: 40),
                );
              },
            ),
          ),
          Container(padding: const EdgeInsets.all(24), decoration: BoxDecoration(color: Colors.white, boxShadow: [BoxShadow(color: Colors.black12, blurRadius: 10)]), child: ElevatedButton(onPressed: _selectedSeatIndex != -1 ? () {} : null, style: ElevatedButton.styleFrom(minimumSize: const Size(double.infinity, 50)), child: const Text('Confirm Seat'))),
        ],
      ),
    );
  }

  Widget _buildLegend(Color color, String text) {
    return Row(children: [Icon(Icons.event_seat, color: color, size: 20), const SizedBox(width: 4), Text(text, style: const TextStyle(fontSize: 12))]);
  }
}

