class CookingStepsScreen extends StatefulWidget {
  const CookingStepsScreen({Key? key}) : super(key: key);
  @override
  State<CookingStepsScreen> createState() => _CookingStepsScreenState();
}

class _CookingStepsScreenState extends State<CookingStepsScreen> {
  int _currentStep = 0;
  final List<String> _steps = [
    'Preheat the oven to 375\u00B0F (190\u00B0C).',
    'Mix the flour, sugar, and baking powder in a large bowl.',
    'Add the eggs and milk, and stir until smooth.',
    'Pour the batter into a greased baking pan.',
    'Bake for 45 minutes or until golden brown.'
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Cooking Instructions')),
      body: Stepper(
        currentStep: _currentStep,
        onStepContinue: () { if (_currentStep < _steps.length - 1) setState(() { _currentStep += 1; }); },
        onStepCancel: () { if (_currentStep > 0) setState(() { _currentStep -= 1; }); },
        steps: List.generate(_steps.length, (index) {
          return Step(
            title: Text('Step ${index + 1}'),
            content: Container(alignment: Alignment.centerLeft, padding: const EdgeInsets.symmetric(vertical: 8), child: Text(_steps[index], style: const TextStyle(fontSize: 16))),
            isActive: _currentStep >= index,
            state: _currentStep > index ? StepState.complete : StepState.indexed,
          );
        }),
      ),
    );
  }
}

