  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        backgroundColor: Colors.transparent,
        elevation: 0,
        leading: IconButton(icon: const Icon(Icons.close, color: Colors.grey), onPressed: () {}),
        title: LinearProgressIndicator(value: 0.4, backgroundColor: Colors.grey[300], valueColor: const AlwaysStoppedAnimation<Color>(Colors.green), minHeight: 10, borderRadius: BorderRadius.circular(5)),
      ),
      body: Padding(
        padding: const EdgeInsets.all(24.0),
